class DSU:
    def __init__(self, n):
        self.p = list(range(n + 1))
        self.components = n
    def find(self, i):
        if self.p[i] == i:
            return i
        self.p[i] = self.find(self.p[i])
        return self.p[i]
    def union(self, i, j):
        pi, pj = self.find(i), self.find(j)
        if pi != pj:
            self.p[pi] = pj
            self.components -= 1
            return True
        return False

class Solution:
    def maxNumEdgesToRemove(self, n: int, edges: list[list[int]]) -> int:
        alice = DSU(n)
        bob = DSU(n)
        used = 0
        for t, u, v in edges:
            if t == 3:
