#include <vector>
#include <numeric>

struct DSU {
    std::vector<int> p;
    int comp;
    DSU(int n) : p(n + 1), comp(n) { std::iota(p.begin(), p.end(), 0); }
    int find(int i) { return p[i] == i ? i : (p[i] = find(p[i])); }
    bool unite(int i, int j) {
        int pi = find(i), pj = find(j);
        if (pi != pj) { p[pi] = pj; comp--; return true; }
        return false;
    }
};

class Solution {
public:
    int maxNumEdgesToRemove(int n, std::vector<std::vector<int>>& edges) {
        DSU alice(n), bob(n);
        int used = 0;
        for (const auto& e : edges) {
            if (e[0] == 3) {
                bool a = alice.unite(e[1], e[2]);
                bool b = bob.unite(e[1], e[2]);
                if (a || b) used++;
            }
        }
        for (const auto& e : edges) {
            if (e[0] == 1) {
                if (alice.unite(e[1], e[2])) used++;
            } else if (e[0] == 2) {
                if (bob.unite(e[1], e[2])) used++;
            }
        }
        if (alice.comp > 1 || bob.comp > 1) return -1;
        return edges.size() - used;
    }
};

import java.util.*;

class Solution {
    static class DSU {
        int[] p;
        int comp;
        DSU(int n) {
            p = new int[n + 1];
            for (int i = 0; i <= n; i++) p[i] = i;
            comp = n;
        }
        int find(int i) { return p[i] == i ? i : (p[i] = find(p[i])); }
        boolean union(int i, int j) {
            int pi = find(i), pj = find(j);
            if (pi != pj) { p[pi] = pj; comp--; return true; }
            return false;
        }
    }
    public int maxNumEdgesToRemove(int n, int[][] edges) {
        DSU alice = new DSU(n);
        DSU bob = new DSU(n);
        int used = 0;
        for (int[] e : edges) {
            if (e[0] == 3) {
                boolean a = alice.union(e[1], e[2]);
                boolean b = bob.union(e[1], e[2]);
                if (a || b) used++;
            }
        }
        for (int[] e : edges) {
            if (e[0] == 1) {
                if (alice.union(e[1], e[2])) used++;
            } else if (e[0] == 2) {
                if (bob.union(e[1], e[2])) used++;
            }
        }
        if (alice.comp > 1 || bob.comp > 1) return -1;
        return edges.length - used;
    }
}

var maxNumEdgesToRemove = function(n, edges) {
    class DSU {
        constructor(n) {
            this.p = Array.from({ length: n + 1 }, (_, i) => i);
            this.comp = n;
        }
        find(i) { return this.p[i] === i ? i : (this.p[i] = this.find(this.p[i])); }
        union(i, j) {
            const pi = this.find(i), pj = this.find(j);
            if (pi !== pj) { this.p[pi] = pj; this.comp--; return true; }
            return false;
        }
    }
    const alice = new DSU(n);
    const bob = new DSU(n);
    let used = 0;
    for (const [t, u, v] of edges) {
        if (t === 3) {
            const a = alice.union(u, v);
            const b = bob.union(u, v);
            if (a || b) used++;
        }
    }
    for (const [t, u, v] of edges) {
        if (t === 1) {
            if (alice.union(u, v)) used++;
        } else if (t === 2) {
            if (bob.union(u, v)) used++;
        }
    }
    if (alice.comp > 1 || bob.comp > 1) return -1;
    return edges.length - used;
};
